INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1451304, 187137, 36981, '<td valign="top">Great shot!  I love the movement of them all, and the fact that they''re wild.</td>', 'Great shot!  I love the movement of them all, and the fact that they''re wild.', '2005-06-13 09:24:42.000000', NULL, 1),
(1451305, 188756, 36981, '<td valign="top">Perfect capture!  I love that you got the wings extended, and the colors in the back are gorgeous.  They complement the bird perfectly.</td>', 'Perfect capture!  I love that you got the wings extended, and the colors in the back are gorgeous.  They complement the bird perfectly.', '2005-06-13 09:26:01.000000', NULL, 1),
(1451306, 189051, 36981, '<td valign="top">I didn''t have the guts to do this myself, but was hoping someone would!  Great picture, made me laugh &amp; great choice of desat!</td>', 'I didn''t have the guts to do this myself, but was hoping someone would!  Great picture, made me laugh & great choice of desat!', '2005-06-13 09:27:33.000000', NULL, 1),
(1451308, 189052, 36981, '<td valign="top">What a funny shot!  I love the bird''s expression, and the way you centered it.  Terrific detail in the head.</td>', 'What a funny shot!  I love the bird''s expression, and the way you centered it.  Terrific detail in the head.', '2005-06-13 09:28:51.000000', NULL, 1),
(1451314, 188967, 36981, '<td valign="top">Fabulous!  I love the pose &amp; the shallow DOF.</td>', 'Fabulous!  I love the pose & the shallow DOF.', '2005-06-13 09:30:23.000000', NULL, 1),
(1451315, 187903, 15029, '<td valign="top">really drmatic shot. amazing timing, and the framing is excelent with the reflection</td>', 'really drmatic shot. amazing timing, and the framing is excelent with the reflection', '2005-06-13 09:30:57.000000', NULL, 1),
(1451318, 187565, 15029, '<td valign="top">LOL!  the expression on this owl is very funny. excelent title to convey the humor</td>', 'LOL!  the expression on this owl is very funny. excelent title to convey the humor', '2005-06-13 09:32:06.000000', NULL, 1),
(1451323, 188822, 15029, '<td valign="top">excelent detail shot, but I don''t like how the very top of the head got cut off</td>', 'excelent detail shot, but I don''t like how the very top of the head got cut off', '2005-06-13 09:33:32.000000', NULL, 1),
(1451327, 187209, 15029, '<td valign="top">what maked this photo interesting is how they are all looking at that one in the bottom right corner, but somehow your framing doesn''t seem to emphasize the same swan. just my 2 cents</td>', 'what maked this photo interesting is how they are all looking at that one in the bottom right corner, but somehow your framing doesn''t seem to emphasize the same swan. just my 2 cents', '2005-06-13 09:35:55.000000', NULL, 1),
(1451328, 188016, 15029, '<td valign="top">nice, but the head seems a touch grainy, especially the black of the throat</td>', 'nice, but the head seems a touch grainy, especially the black of the throat', '2005-06-13 09:37:02.000000', NULL, 1),
(1451330, 188282, 15029, '<td valign="top">the framing  is a bit constricted imho. it looks like the falcon is hunched over to stay in the frame</td>', 'the framing  is a bit constricted imho. it looks like the falcon is hunched over to stay in the frame', '2005-06-13 09:38:19.000000', NULL, 1),
