INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1452358, 188811, 35645, '<td valign="top">Wonderful textures and colors. It''s a bit annoying that the top of his head is cut off by the border.</td>', 'Wonderful textures and colors. It''s a bit annoying that the top of his head is cut off by the border.', '2005-06-13 15:34:17.000000', NULL, 1),
