(1452361, 186654, 35645, '<td valign="top">Made me smile. Nice composition, great lighting, really great capture.</td>', 'Made me smile. Nice composition, great lighting, really great capture.', '2005-06-13 15:35:37.000000', NULL, 1),
(1452363, 188924, 39116, '<td valign="top">would have loved a little more detail of bird....</td>', 'would have loved a little more detail of bird....', '2005-06-13 15:36:17.000000', NULL, 1),
