(1453470, 188930, 7810, '<td valign="top">nice detail and colour beautiful image</td>', 'nice detail and colour beautiful image', '2005-06-13 23:07:20.000000', NULL, 1),
(1453498, 186994, 37700, '<td valign="top">Great emphasis on the eyes, wonderfull detail in the feathers. Good effort deserves to score well.</td>', 'Great emphasis on the eyes, wonderfull detail in the feathers. Good effort deserves to score well.', '2005-06-13 23:33:38.000000', NULL, 1),
(1453507, 188546, 37700, '<td valign="top">What a HOOT. Seriously -" love it",  great expression plenty of shapes and detail to lead you around this composition, always leading you back to the eyes.</td>', 'What a HOOT. Seriously -" love it",  great expression plenty of shapes and detail to lead you around this composition, always leading you back to the eyes.', '2005-06-13 23:40:05.000000', NULL, 1),
