INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1454740, 188673, 24454, '<td valign="top">Awwwww. . . he is SO CUTE.    I love it that he''s in a different setting than just on a river bank or floating around in the water.     This is nice.   He''s all by himself, posing on the boulders.   Nice job!</td>', 'Awwwww. . . he is SO CUTE.    I love it that he''s in a different setting than just on a river bank or floating around in the water.     This is nice.   He''s all by himself, posing on the boulders.   Nice job!', '2005-06-14 12:41:07.000000', NULL, 1),
(1454741, 188646, 31443, '<td valign="top">Good thing you didn''t get any closer, those Swans don''t look too friendly :( nice shot though</td>', 'Good thing you didn''t get any closer, those Swans don''t look too friendly :( nice shot though', '2005-06-14 12:41:18.000000', NULL, 1),
(1454743, 188076, 38327, '<td valign="top">Beautiful lighting, perfect speed &amp; depth.  I especially appreciate the contrast of colors and the similarity between the angle of the bird''s body and the left edgeline of the trees.</td>', 'Beautiful lighting, perfect speed & depth.  I especially appreciate the contrast of colors and the similarity between the angle of the bird''s body and the left edgeline of the trees.', '2005-06-14 12:42:13.000000', NULL, 1),
(1454744, 188338, 24454, '<td valign="top">That''s a beautiful eagle!   Is it even possible to take a picture of an eagle that doesn''t look noble and regal??    Maybe a tiny bit more depth of field would have made all his feathers on top of his head sharp and focused, but it''s still a beautiful shot anyway!</td>', 'That''s a beautiful eagle!   Is it even possible to take a picture of an eagle that doesn''t look noble and regal??    Maybe a tiny bit more depth of field would have made all his feathers on top of his head sharp and focused, but it''s still a beautiful shot anyway!', '2005-06-14 12:43:09.000000', NULL, 1),
(1454749, 188668, 31443, '<td valign="top">Beautiful shot and different, this light is amazing!</td>', 'Beautiful shot and different, this light is amazing!', '2005-06-14 12:44:34.000000', NULL, 1),
(1454754, 188988, 31443, '<td valign="top">The color of the beaks don''t look very natural, maybe a tad overexposed..</td>', 'The color of the beaks don''t look very natural, maybe a tad overexposed..', '2005-06-14 12:47:18.000000', NULL, 1),
(1454758, 188230, 6668, '<td valign="top">The birds have so much expression in there faces..nice capture!</td>', 'The birds have so much expression in there faces..nice capture!', '2005-06-14 12:48:28.000000', NULL, 1),
