(1455980, 188915, 6179, '<td valign="top">Like the composition. The blurred background and the sharp focus on the subject really makes this photo stand out.</td>', 'Like the composition. The blurred background and the sharp focus on the subject really makes this photo stand out.', '2005-06-14 23:06:18.000000', NULL, 1),
(1455982, 188441, 6179, '<td valign="top">Good detail and color captured here. You could have used slighly more DOF to get the leaves in the foreground in focus while still maintaining the blurred background.</td>', 'Good detail and color captured here. You could have used slighly more DOF to get the leaves in the foreground in focus while still maintaining the blurred background.', '2005-06-14 23:07:37.000000', NULL, 1),
(1455986, 189047, 6179, '<td valign="top">Colors look a bit washed out for some reason.</td>', 'Colors look a bit washed out for some reason.', '2005-06-14 23:08:59.000000', NULL, 1),
(1455988, 187843, 6179, '<td valign="top">not the best choice of cropping here. You really need to see a little more of the subject in this case.  The focus also leaves a little room for improvement.</td>', 'not the best choice of cropping here. You really need to see a little more of the subject in this case.  The focus also leaves a little room for improvement.', '2005-06-14 23:10:11.000000', NULL, 1),
(1455991, 188972, 6179, '<td valign="top">Nice effect.</td>', 'Nice effect.', '2005-06-14 23:11:03.000000', NULL, 1);
