(1456564, 189021, 17279, '<td valign="top">Very nice capture, but the background is too blown out and really detracts from the main subject.</td>', 'Very nice capture, but the background is too blown out and really detracts from the main subject.', '2005-06-15 02:24:31.000000', NULL, 1),
(1456570, 188698, 17279, '<td valign="top">I was really drawn to the eye on this one, but the leaves really detract from the bird.</td>', 'I was really drawn to the eye on this one, but the leaves really detract from the bird.', '2005-06-15 02:26:39.000000', NULL, 1),
(1456572, 188915, 17279, '<td valign="top">Beautiful.  I''m not sure if the subject being so centered really works with this shot.</td>', 'Beautiful.  I''m not sure if the subject being so centered really works with this shot.', '2005-06-15 02:27:33.000000', NULL, 1),
(1456582, 186160, 17279, '<td valign="top">Beautiful eyes.  I think the multi-colored background hurts the impact on this image though.</td>', 'Beautiful eyes.  I think the multi-colored background hurts the impact on this image though.', '2005-06-15 02:29:09.000000', NULL, 1),
