(1465484, 188737, 22734, '<td valign="top">Great capture bringing out the alertness.</td>', 'Great capture bringing out the alertness.', '2005-06-18 15:33:33.000000', NULL, 1),
(1465486, 189033, 22734, '<td valign="top">Cute little fellow.</td>', 'Cute little fellow.', '2005-06-18 15:35:24.000000', NULL, 1),
(1465491, 187644, 22734, '<td valign="top">One of those exceptional title that indeed help accentuate the capture even more.</td>', 'One of those exceptional title that indeed help accentuate the capture even more.', '2005-06-18 15:38:07.000000', NULL, 1),
(1465492, 188446, 22734, '<td valign="top">Veru funny. I can see doing this to a dog but not a cat. Hilarious.</td>', 'Veru funny. I can see doing this to a dog but not a cat. Hilarious.', '2005-06-18 15:39:13.000000', NULL, 1),
