(1467827, 189021, 22734, '<td valign="top">Looks like a spacecraft. A most convincing action capture.</td>', 'Looks like a spacecraft. A most convincing action capture.', '2005-06-20 00:14:59.000000', NULL, 1),
(1467829, 188255, 22734, '<td valign="top">These birds are always in motion. Good capture.</td>', 'These birds are always in motion. Good capture.', '2005-06-20 00:15:29.000000', NULL, 1),
(1467846, 188099, 22734, '<td valign="top">Lovely composition. These are beauties.</td>', 'Lovely composition. These are beauties.', '2005-06-20 00:20:29.000000', NULL, 1),
(1467850, 189025, 22734, '<td valign="top">What a cutie. Blends right into wood.</td>', 'What a cutie. Blends right into wood.', '2005-06-20 00:21:53.000000', NULL, 1),
(1467857, 188015, 22734, '<td valign="top">Such unadulterated sweetness. A true beauty and fine comapnion.</td>', 'Such unadulterated sweetness. A true beauty and fine comapnion.', '2005-06-20 00:23:44.000000', NULL, 1),
(1467865, 188546, 22734, '<td valign="top">This is indeed a superlative image which hooks the viewer. This is one of my favorites for this challenge. You get the good bump. 10</td>', 'This is indeed a superlative image which hooks the viewer. This is one of my favorites for this challenge. You get the good bump. 10', '2005-06-20 00:25:03.000000', NULL, 1),
(1467866, 188934, 22734, '<td valign="top">An outstanding capture that is certain to please all viewers. Bumping up into contention area. 9</td>', 'An outstanding capture that is certain to please all viewers. Bumping up into contention area. 9', '2005-06-20 00:25:22.000000', NULL, 1),
